import csv, io
row = ['a b', 'c,d', 7, None, '']
def line(q):
    s = io.StringIO(newline='')
    csv.writer(s, quoting=q, escapechar='\\').writerow(row)
    return s.getvalue()
names = ['QUOTE_MINIMAL', 'QUOTE_ALL', 'QUOTE_NONNUMERIC',
         'QUOTE_NONE', 'QUOTE_STRINGS', 'QUOTE_NOTNULL']
for q in names: print(q, repr(line(getattr(csv, q))))

