import csv, io
text = 'Region,Sales\r\nNorth,120\r\nSouth,80\r\nNorth,60\r\nEast,40\r\n'
totals = {}
for row in csv.DictReader(io.StringIO(text, newline='')):
    totals[row['Region']] = totals.get(row['Region'], 0) + int(row['Sales'])
print(totals)

import json
def msg(t):
    try: json.loads(t); return 'accepted'
    except json.JSONDecodeError as e: return '%s (column %d)' % (e.msg, e.colno)
texts = ['["spam", "eggs",]', "{'a': 1}", '[None]', '[NaN]', '']
for t in texts:
    print(repr(t), '->', msg(t))

import xml.etree.ElementTree as ET
a = ET.fromstring('<a>\n  <b>x</b>\n</a>')
print(repr(a.text), repr(a[0].tail), repr(a[0].text))
for bad in ('<a><b></a>', '<a/><b/>', '<A></a>'):
    try: ET.fromstring(bad)
    except ET.ParseError as e: print(bad, '->', e)
